var ps = Lower(Trim(DefaultValue($feature.Planning_Status, "")));
if (ps == "scheduled") {
 return "- Prepare for the testing by pouring 3-4 cups of water down all your drains now.";
}
return null;

var s = Trim($feature.Planning_Status);
// 1) If status is Completed show it as
if (s == "Completed") {
 return "Area completed";
}
if (s == "Scheduled") {
 return "Upcoming";
}
if (s == "Planned") {
 return "Date not set, please check back later";
}
// 2) If status is one of the “Not Complete” scenarios, show your message
var notTriggers = [
 "Not Complete_see comments",
 "Not Complete_sewer larger than 675mm",
 "Resident requested to not complete"
];
if (Includes(notTriggers, s)) {
 return "Area completed";
}
// 3) Otherwise show nothing
return Null;
